def _md_escape(text: str | None) -> str:
    value = str(text or "")
    value = value.replace("\\", "\\\\")
    for ch in "_*[]()~`>#+-=|{}.!" :
        value = value.replace(ch, f"\\{ch}")
    return value

def _plain(value: str | None, fallback: str = "Player") -> str:
    return str(value or fallback)

def safe_markdown_name(user_id: int | None, username: str | None, first_name: str | None) -> str:
    if username:
        return f"@{_md_escape(username)}"
    name = _md_escape(first_name or "Player")
    if user_id is None:
        return name
    return f"[{name}](tg://user?id={user_id})"

def safe_username(username: str | None) -> str:
    return f"@{_md_escape(username)}" if username else "Player"

resolve_toss = _resolve_toss
normalize_toss_call = _normalize_toss_call

@dataclass(slots=True)
class ParticipantRef:
    user_id: int | None
    username: str | None = None
    first_name: str | None = None

    def display(self) -> str:
        return safe_markdown_name(self.user_id, self.username, self.first_name)

@dataclass(slots=True)
class BallBlueprint:
    experience: str
    intent: str
    delivery_type: str
    line: str
    length: str
    foot_movement: str
    stroke_type: str
    recommended_shot: str
    match_quality: str

    def key(self) -> tuple[str, str, str, str, str, str, str]:
        return (
            self.experience,
            self.intent,
            self.delivery_type,
            self.line,
            self.length,
            self.foot_movement,
            self.stroke_type,
        )

@dataclass(slots=True)
class MatchSession:
    match_id: int | None
    challenge_id: int | None
    chat_id: int
