def match_starting_message(winner_display: str, decision: str, format_: str) -> str:
    decision_text = _md_escape(decision.upper())
    return (
        f"*🎯 DECISION LOCKED*\n\n"
        f"*Winner:* {winner_display}\n"
        f"*Decision:* {decision_text}\n"
        f"*Format:* {format_}\n\n"
        f"*The stadium is ready. The next stage begins now.*"
    )

def reminder_message(user_display: str, remaining: int, action: str) -> str:
    unit = "minute" if remaining == 60 else "second"
    return f"⏰ {user_display}, *{remaining // 60 if remaining >= 60 else remaining} {unit}{'' if (remaining == 1 or remaining == 60) else 's'} remaining* to {action}!"

class MatchEngine:
    def __init__(self):
        self.sessions: dict[int, MatchSession] = {}

    def create_session(
        self,
        *,
        chat_id: int,
        challenger_id: int,
        opponent_id: int,
        challenger_username: str | None = None,
        opponent_username: str | None = None,
        challenger_name: str | None = None,
        opponent_name: str | None = None,
        match_id: int | None = None,
        challenge_id: int | None = None,
        format_: str = DEFAULT_MATCH_FORMAT,
    ) -> MatchSession:
        session = MatchSession(
            match_id=match_id,
            challenge_id=challenge_id,
            chat_id=chat_id,
            challenger=ParticipantRef(challenger_id, challenger_username, challenger_name),
            opponent=ParticipantRef(opponent_id, opponent_username, opponent_name),
            format=format_,
        )
        self.sessions[chat_id] = session
        try:
            update_game(chat_id, stage=session.stage, match_id=match_id, data={"challenge_id": challenge_id, "format": format_})
        except Exception:
            pass
        return session

    def get_session(self, chat_id: int) -> MatchSession | None:
        return self.sessions.get(chat_id)

    def clear_session(self, chat_id: int) -> None:
        self.sessions.pop(chat_id, None)
        try:
            clear_game(chat_id)
        except Exception:
            pass

    def register_challenge(self, session: MatchSession) -> None:
        session.stage = "challenge"
        session.meta["registered_at"] = time.time()

    def confirm_challenge(self, session: MatchSession) -> None:
        session.stage = "confirmed"
        session.meta["confirmed_at"] = time.time()
        try:
            update_game(session.chat_id, stage=session.stage, data={"confirmed_at": session.meta["confirmed_at"]})
        except Exception:
            pass

    def start_toss(self, session: MatchSession) -> None:
        session.stage = "toss"
        try:
            update_game(session.chat_id, stage=session.stage)
        except Exception:
            pass

    def record_toss_call(self, session: MatchSession, call: str, actual: str, winner_id: int) -> None:
        session.toss_call = call
        session.toss_result = actual
        session.toss_winner_id = winner_id
        session.stage = "decision"
        try:
            update_game(session.chat_id, stage=session.stage, data={"toss_call": call, "toss_result": actual, "toss_winner_id": winner_id})
        except Exception:
            pass

    def record_decision(self, session: MatchSession, decision: str) -> None:
        session.decision = decision
        session.stage = "lineup"
        try:
            update_game(session.chat_id, stage=session.stage, data={"decision": decision})
        except Exception:
            pass

    def set_batting_order(self, session: MatchSession, batting_order: list[dict[str, Any]]) -> None:
        session.batting_order = list(batting_order)
        try:
            update_game(session.chat_id, data={"batting_order": session.batting_order})
        except Exception:
            pass

    def set_bowling_order(self, session: MatchSession, bowling_order: list[dict[str, Any]]) -> None:
        session.bowling_order = list(bowling_order)
        session.meta["bowling_queue"] = list(bowling_order)
        session.meta["bowler_index"] = 0
        try:
            update_game(session.chat_id, data={"bowling_order": session.bowling_order})
        except Exception:
            pass

    def set_delivery_type(self, session: MatchSession, delivery_type: str | None) -> None:
        session.selected_delivery = delivery_type
        session.selected_line = None
        session.selected_length = None
        session.selected_foot = None
        session.selected_stroke_type = None
        session.selected_intent = None
        session.selected_shot = None
        session.stage = "delivery_line"
        try:
            update_game(session.chat_id, stage=session.stage, data={"selected_delivery": delivery_type})
        except Exception:
            pass

    def set_line(self, session: MatchSession, line: str | None) -> None:
        session.selected_line = line
        session.stage = "delivery_length" if (session.selected_delivery not in {"Yorker Ball", "Bouncer Ball"}) else "foot_movement"
        try:
            update_game(session.chat_id, stage=session.stage, data={"selected_line": line})
        except Exception:
            pass

    def set_length(self, session: MatchSession, length: str | None) -> None:
        session.selected_length = length
        session.stage = "foot_movement"
        try:
            update_game(session.chat_id, stage=session.stage, data={"selected_length": length})
        except Exception:
            pass

    def set_foot_movement(self, session: MatchSession, foot: str | None) -> None:
        session.selected_foot = foot
        session.selected_stroke_type = None
        session.selected_shot = None
        session.stage = "stroke_type"
        try:
            update_game(session.chat_id, stage=session.stage, data={"selected_foot": foot})
        except Exception:
            pass

    def set_stroke_type(self, session: MatchSession, stroke_type: str | None) -> None:
        session.selected_stroke_type = stroke_type
        session.selected_shot = None
        session.stage = "shot_choice"
        try:
            update_game(session.chat_id, stage=session.stage, data={"selected_stroke_type": stroke_type})
        except Exception:
            pass

    def set_shot(self, session: MatchSession, shot: str | None) -> None:
        session.selected_shot = shot
        session.stage = "playing"
        try:
            update_game(session.chat_id, stage=session.stage, data={"selected_shot": shot})
        except Exception:
            pass

    def reset_ball_plan(self, session: MatchSession) -> None:
        session.selected_delivery = None
        session.selected_line = None
        session.selected_length = None
        session.selected_foot = None
        session.selected_stroke_type = None
        session.selected_intent = None
        session.selected_shot = None

    def advance_bowler(self, session: MatchSession) -> dict[str, Any] | None:
        queue = list(session.meta.get("bowling_queue") or session.bowling_order or [])
        if not queue:
            return None
        index = int(session.meta.get("bowler_index", 0))
        index = (index + 1) % len(queue)
        session.meta["bowler_index"] = index
        session.current_bowler = queue[index]
        try:
            update_game(session.chat_id, data={"current_bowler": session.current_bowler, "bowler_index": index})
        except Exception:
            pass
        return session.current_bowler

    def start_innings(self, session: MatchSession, batting_order: list[dict[str, Any]] | None = None) -> InningsState:
        if batting_order is not None:
            self.set_batting_order(session, batting_order)
        if len(session.batting_order) < 2:
            raise ValueError("Need at least two batters to start an innings")
        order = [BatterSlot(name=p.get("name", "Player"), role=p.get("role"), bat_level=p.get("bat_level"), bowl_level=p.get("bowl_level")) for p in session.batting_order]
        innings = create_innings(
            batting_team_id=session.challenger.user_id,
            bowling_team_id=session.opponent.user_id,
            batting_order=order,
            innings_number=1,
        )
        session.innings = innings
        session.stage = "playing"
        try:
            update_game(session.chat_id, stage=session.stage, data={"innings_number": 1, "score": innings.snapshot()["score"]})
        except Exception:
            pass
        return innings

    def current_batsman_name(self, session: MatchSession) -> str:
        if session.innings and session.innings.striker:
            return session.innings.striker.name
        if session.current_batsman:
            return _plain(session.current_batsman.get("name"))
        return "Player"

    def current_bowler_name(self, session: MatchSession) -> str:
        if session.current_bowler:
            return _plain(session.current_bowler.get("name"))
        return "Bowler"

    def build_ball_context(self, session: MatchSession) -> BallContext:
        batsman_level = int((session.current_batsman or {}).get("bat_level", 50) or 50)
        bowler_level = int((session.current_bowler or {}).get("bowl_level", 50) or 50)
        foot_movement = session.selected_foot
        stroke_type = session.selected_stroke_type
        approach = "ADVANCE" if (foot_movement or "").strip().lower() == "advance" else (
            "LOFT" if (stroke_type or "").strip().lower() == "lofted shot" else "GROUND"
        )
        over_number = 1
        if session.innings is not None:
            over_number = int((session.innings.score.legal_balls // 6) + 1)
        return BallContext(
            bowler_level=bowler_level,
            batsman_level=batsman_level,
            balls_faced=session.balls_faced,
            delivery_type=session.selected_delivery,
            line=session.selected_line,
            length=session.selected_length,
            foot_movement=foot_movement,
            stroke_type=stroke_type,
            stroke_intent=session.selected_intent,
            specific_shot=session.selected_shot,
            bowler_is_pace_or_spin=infer_bowler_type(session.selected_delivery or "Fast Ball"),
            batsman_experience=experience_tier(session.balls_faced),
            over_number=over_number,
            pitch=session.meta.get("pitch"),
            approach=approach,
        )

    def resolve_ball(self, session: MatchSession) -> dict[str, Any]:
        context = self.build_ball_context(session)
        outcome = resolve_ball(
            bowler_level=context.bowler_level,
            batsman_level=context.batsman_level,
            balls_faced=context.balls_faced,
            stroke_type=context.stroke_type or "Ground Shot",
            stroke_intent=context.stroke_intent or "Neutral",
            shot_match_quality=context.shot_match_quality or "neutral",
            delivery_type=context.delivery_type,
            line=context.line,
            length=context.length,
            foot_movement=context.foot_movement,
            specific_shot=context.specific_shot,
            bowler_is_pace_or_spin=context.bowler_is_pace_or_spin,
            batsman_experience=context.batsman_experience,
            random_variation=False,
        )
        runs_map = {"dot": 0, "single": 1, "double": 2, "triple": 3, "four": 4, "five": 5, "boundary": 4, "six": 6, "wide": 1, "no_ball": 1, "leg_bye": 1, "bye": 1, "out": 0, "run_out": 0, "mishit": 0}
        is_wicket = outcome in {"out", "run_out"}
        session.balls_faced += 1 if outcome not in {"wide", "no_ball"} else 0
        session.score = update_score_from_ball(
            session.score,
            outcome=outcome,
            runs=runs_map.get(outcome, 0),
            wicket=is_wicket,
            batter_name=self.current_batsman_name(session),
            legal_delivery=outcome not in {"wide", "no_ball"},
        )
        over_ended = False
        if session.innings is not None:
            before_legal_balls = session.innings.score.legal_balls
            _register_innings_ball(
                session.innings,
                outcome=outcome,
                runs=runs_map.get(outcome, 0),
                wicket=is_wicket,
                batter_name=self.current_batsman_name(session),
                legal_delivery=outcome not in {"wide", "no_ball"},
            )
            over_ended = session.innings.score.legal_balls > before_legal_balls and session.innings.score.legal_balls % 6 == 0
            if over_ended:
                next_bowler = self.advance_bowler(session)
                if next_bowler is not None:
                    result_bowler = next_bowler.get("name") or "Bowler"
                else:
                    result_bowler = None
            else:
                result_bowler = None
        else:
            result_bowler = None
        result = {
            "outcome": outcome,
            "runs": runs_map.get(outcome, 0),
            "wicket": is_wicket,
            "score": ball_summary(session.score),
            "commentary": describe_ball_result({
                "outcome": outcome,
                "runs": runs_map.get(outcome, 0),
                "batter_name": self.current_batsman_name(session),
                "bowler_name": self.current_bowler_name(session),
                "shot_name": session.selected_shot,
                "delivery_name": session.selected_delivery,
                "line": session.selected_line,
                "length": session.selected_length,
            }),
            "next_bowler": result_bowler,
            "blueprint": suggest_blueprint(
                bowler_level=context.bowler_level,
                batsman_level=context.batsman_level,
                balls_faced=context.balls_faced,
                delivery_type=session.selected_delivery or "Fast Ball",
                line=session.selected_line or "Middle Stump",
                length=session.selected_length or "Good Length",
                foot_movement=session.selected_foot or "Front Foot",
                stroke_type=session.selected_stroke_type or "Ground Shot",
                stroke_intent=session.selected_intent or "Neutral",
                specific_shot=session.selected_shot,
                bowler_is_pace_or_spin=context.bowler_is_pace_or_spin,
            ),
        }
        session.history.append(result)
        session.commentary.append(result["commentary"])
        return result

    def is_match_complete(self, session: MatchSession) -> bool:
        target = session.innings.target if session.innings else None
        return innings_finished(session.score, target=target)

    def summary(self, session: MatchSession) -> str:
        return over_summary(session.score.runs, session.score.wickets, format_over(session.score.legal_balls))

    def promote_next_innings(self, session: MatchSession) -> InningsState:
        if session.innings is None:
            raise RuntimeError("Innings has not started yet")
        next_state = _advance_innings(session.innings, new_batting_team_id=session.opponent.user_id, new_bowling_team_id=session.challenger.user_id)
        session.stage = "playing"
        return next_state

MATCH_ENGINE = MatchEngine()

def get_match_session(chat_id: int) -> MatchSession | None:
    return MATCH_ENGINE.get_session(chat_id)

def clear_match_session(chat_id: int) -> None:
    MATCH_ENGINE.clear_session(chat_id)

